import math

def g(n):
    return 18*n + 9 - 42 * math.floor((n+2)/4)

def check_equation(a, b):
    lhs = g(a + g(a) + b) - g(a + b)
    rhs = g(a - b) - g(a - g(a) - b)
    return lhs == rhs

# Test for some range of a, b
all_pass = True
for a in range(-10, 11):
    for b in range(-10, 11):
        if not check_equation(a, b):
            all_pass = False
            print(f"Failed for a={a}, b={b}")
            break
    if not all_pass:
        break

print(f"All pass: {all_pass}")
if all_pass:
    print(f"g(2025) = {g(2025)}")

